python3 -c "
import json
with open('/app/resources/treasury_bulletin_1987_12.json', 'r') as f:
    data = json.load(f)

# Print the structure
if isinstance(data, dict):
    print('Top-level keys:', list(data.keys())[:20])
    for key in list(data.keys())[:5]:
        if isinstance(data[key], dict):
            print(f'  {key} keys:', list(data[key].keys())[:10])
        elif isinstance(data[key], list):
            print(f'  {key} is list with', len(data[key]), 'items')
            if data[key] and isinstance(data[key][0], dict):
                print(f'    first item keys:', list(data[key][0].keys())[:10])
"
